def check_dict_case(d):
    if not d:
        return False

    all_lower = all_upper = True

    for key in d.keys():
        if not isinstance(key, str):
            return False
        if all_lower and not key.islower():
            all_lower = False
        if all_upper and not key.isupper():
            all_upper = False

    return all_lower or all_upper

